packages/jcode/package.nix
{
  lib,
  flake,
  stdenvNoCC,
  bun,
  fetchFromGitHub,
  versionCheckHook,
}:
let
  version = "0.1.0";
  src = fetchFromGitHub {
    owner = "smdex";
    repo = "pi-perplexity";
    rev = "0d15be4fa17f70be06d21e6e9c7fc1abe66b1346";
    hash = "sha256-QcUyjrRHKhRRuQlN5qyEhPzG85F9GIXB5cd8cQF6sHE=";
  };
  cli = "${src}/cli";
  bunDeps = stdenvNoCC.mkDerivation {
    pname = "pplx-bun-deps";
    inherit version;
    src = cli;
    nativeBuildInputs = [ bun ];
    buildPhase = ''
      export HOME=$TMPDIR XDG_CACHE_HOME=$TMPDIR/xdg-cache
      bun install --frozen-lockfile --production --ignore-scripts --no-progress
    '';
    installPhase = ''
      mkdir -p $out
      cp -R node_modules $out/node_modules
    '';
    dontFixup = true;
    outputHashAlgo = "sha256";
    outputHashMode = "recursive";
    outputHash = "sha256-A0MWvmLAsI0yMr6rvYRYbDuS0sZAP53lrN3WhmtHQ2c=";
  };
in
stdenvNoCC.mkDerivation {
  pname = "pplx";
  inherit version;
  src = cli;
  nativeBuildInputs = [ bun ];
  buildPhase = ''
    cp -R ${bunDeps}/node_modules ./node_modules
    chmod -R u+w node_modules
    export HOME=$TMPDIR XDG_CACHE_HOME=$TMPDIR/xdg-cache
    bun build --target=bun --minify --outfile=pplx.js ./src/index.ts
  '';
  installPhase = ''
    install -Dm644 pplx.js $out/lib/pplx/pplx.js
    install -Dm755 pplx.js $out/bin/pplx
    patchShebangs $out/bin/pplx
    install -Dm644 ${cli}/skills/perplexity-cli/SKILL.md $out/share/pplx/skills/perplexity-cli/SKILL.md
  '';
  doInstallCheck = true;
  nativeInstallCheckInputs = [ versionCheckHook ];
  passthru.category = "Utilities";
  meta = {
    description = "Perplexity CLI for cited answers, research, and threads";
    homepage = "https://github.com/smdex/pi-perplexity";
    changelog = "https://github.com/smdex/pi-perplexity/commits/${src.rev}";
    license = lib.licenses.mit;
    sourceProvenance = with lib.sourceTypes; [ fromSource ];
    maintainers = with flake.lib.maintainers; [ smdex ];
    mainProgram = "pplx";
    platforms = lib.platforms.all;
  };
}
{
  lib,
  flake,
  rustPlatform,
  fetchFromGitHub,
  cmake,
  pkg-config,
  openssl,
  versionCheckHook,
  versionCheckHomeHook,
}:

rustPlatform.buildRustPackage (finalAttrs: {
  pname = "jcode";
  version = "0.91.0";

  src = fetchFromGitHub {
    owner = "smdex";
    repo = "jcode";
    rev = "1b434d4ceed0ff93265153cf2012a24cd214025a";
    hash = "sha256-xuNwx8lHDBk7d4tNMlRoXpFWwgNwlzP4kIEZt1jQsr4=";
  };

  cargoHash = "sha256-p5qKX+MFC44aZ5OZ5iJxCj0sY6pdQMsEPNzuXdmsd3Q=";

  # .cargo/config.toml caps builds at 4 jobs; let Nix parallelism decide.
  postPatch = ''
    rm .cargo/config.toml
  '';

  # aws-lc-sys (rustls provider) needs cmake; imap's default native-tls
  # backend links against system openssl.
  nativeBuildInputs = [
    cmake
    pkg-config
  ];

  buildInputs = [ openssl ];

  # Make the embedded version string a release one ("vX.Y.Z") instead of a
  # dev one; the build script falls back to "unknown" git metadata, which is
  # fine for tarball builds.
  env.JCODE_RELEASE_BUILD = "1";

  # Test suite needs network access, provider credentials and a TTY.
  doCheck = false;

  doInstallCheck = true;
  nativeInstallCheckInputs = [
    versionCheckHook
    versionCheckHomeHook
  ];

  passthru.category = "AI Coding Agents";

  meta = with lib; {
    description = "RAM-efficient coding agent TUI with multi-model support and swarm coordination";
    homepage = "https://github.com/smdex/jcode";
    changelog = "https://github.com/smdex/jcode/commit/${finalAttrs.src.rev}";
    license = licenses.mit;
    sourceProvenance = with sourceTypes; [ fromSource ];
    maintainers = with flake.lib.maintainers; [ smdex ];
    mainProgram = "jcode";
    platforms = platforms.unix;
  };
})
{
  lib,
  flake,
  buildGoModule,
  fetchFromGitHub,
  versionCheckHook,
}:

buildGoModule (finalAttrs: {
  pname = "multica";
  version = "0.6.1";

  src = fetchFromGitHub {
    owner = "multica-ai";
    repo = "multica";
    tag = "v${finalAttrs.version}";
    hash = "sha256-I8aD9pyeTuuU2EPn2IwKomWmeAjHxdT0HmEwvo4hVSc=";
  };

  sourceRoot = "${finalAttrs.src.name}/server";
  subPackages = [ "cmd/multica" ];

  vendorHash = "sha256-b6elV4j+7R6L29q8tbCI3MAOY8X63ndzlmCMv7jo7mM=";

  ldflags = [ "-X main.version=${finalAttrs.version}" ];

  doCheck = false;

  doInstallCheck = true;
  nativeInstallCheckInputs = [ versionCheckHook ];

  passthru.category = "AI Assistants";

  meta = {
    description = "Command-line interface for the Multica platform";
    homepage = "https://github.com/multica-ai/multica";
    changelog = "https://github.com/multica-ai/multica/releases/tag/v${finalAttrs.version}";
    license = flake.lib.licenses.unfree;
    sourceProvenance = with lib.sourceTypes; [ fromSource ];
    maintainers = with flake.lib.maintainers; [ smdex ];
    mainProgram = "multica";
    platforms = lib.platforms.unix;
  };
})

